  faq_what_is_a: {
    en: 'Decentralized protocol on Polygon blockchain. All payments in USDC go directly to your wallet through a smart contract — no middlemen, no central authority. The contract handles all distributions automatically and transparently.',
    ru: 'Децентрализованный протокол на блокчейне Polygon. Все платежи в USDC идут напрямую на ваш кошелёк через смарт-контракт — без посредников и центрального управления. Контракт автоматически и прозрачно распределяет все средства.',
    ua: 'Децентралізований протокол на блокчейні Polygon. Всі платежі в USDC йдуть прямо на ваш гаманець через смарт-контракт — без посередників та центрального управління.',
    es: 'Protocolo descentralizado en la blockchain Polygon. Todos los pagos en USDC van directamente a tu wallet a través de un contrato inteligente — sin intermediarios.',
    pt: 'Protocolo descentralizado na blockchain Polygon. Todos os pagamentos em USDC vão diretamente para sua carteira através de um contrato inteligente.',
    fr: 'Protocole décentralisé sur la blockchain Polygon. Tous les paiements en USDC vont directement dans votre portefeuille via un contrat intelligent.',
    de: 'Dezentrales Protokoll auf der Polygon-Blockchain. Alle USDC-Zahlungen gehen direkt über einen Smart Contract an Ihr Wallet.',
    pl: 'Zdecentralizowany protokół na blockchainie Polygon. Wszystkie płatności USDC trafiają bezpośrednio na twój portfel przez smart kontrakt.',
    vi: 'Giao thức phi tập trung trên blockchain Polygon. Tất cả thanh toán USDC đi thẳng đến ví của bạn qua hợp đồng thông minh.',
    ko: 'Polygon 블록체인의 탈중앙화 프로토콜. 모든 USDC 결제가 스마트 컨트랙트를 통해 직접 지갑으로 전송됩니다.',
    ja: 'Polygonブロックチェーン上の分散型プロトコル。すべてのUSDC支払いがスマートコントラクトを通じて直接ウォレットに送られます。',
    hi: 'Polygon ब्लॉकचेन पर विकेंद्रीकृत प्रोटोकॉल। सभी USDC भुगतान स्मार्ट कॉन्ट्रैक्ट के माध्यम से सीधे आपके वॉलेट में जाते हैं।',
    zh: 'Polygon区块链上的去中心化协议。所有USDC支付通过智能合约直接到达您的钱包。',
    tr: 'Polygon blok zincirinde merkeziyetsiz protokol. Tüm USDC ödemeleri akıllı sözleşme aracılığıyla doğrudan cüzdanınıza gider.',
    ar: 'بروتوكول لامركزي على بلوكتشين Polygon. جميع المدفوعات بعملة USDC تذهب مباشرة إلى محفظتك عبر العقد الذكي — بدون وسطاء وبدون سلطة مركزية. يتولى العقد جميع التوزيعات تلقائياً وبشفافية.',
    th: 'โปรโตคอลแบบกระจายศูนย์บนบล็อกเชน Polygon การชำระเงินทั้งหมดเป็น USDC ไปยังกระเป๋าเงินของคุณโดยตรงผ่านสัญญาอัจฉริยะ — ไม่มีคนกลาง ไม่มีหน่วยงานส่วนกลาง สัญญาจัดการการกระจายทั้งหมดโดยอัตโนมัติและโปร่งใส',
    id: 'Protokol terdesentralisasi di blockchain Polygon. Semua pembayaran dalam USDC langsung masuk ke dompet Anda melalui kontrak pintar — tanpa perantara, tanpa otoritas pusat. Kontrak menangani semua distribusi secara otomatis dan transparan.',
    tl: 'Desentralisadong protocol sa Polygon blockchain. Lahat ng bayad sa USDC ay diretso sa iyong wallet sa pamamagitan ng smart contract — walang tagapamagitan, walang sentral na awtoridad. Ang contract ang namamahala ng lahat ng distribusyon nang awtomatiko at transparent.',
    ms: 'Protokol terdesentralisasi di blockchain Polygon. Semua pembayaran dalam USDC terus ke dompet anda melalui kontrak pintar — tiada orang tengah, tiada pihak berkuasa pusat. Kontrak mengendalikan semua pengagihan secara automatik dan telus.',
    it: 'Protocollo decentralizzato sulla blockchain Polygon. Tutti i pagamenti in USDC vanno direttamente al tuo portafoglio tramite smart contract — nessun intermediario, nessuna autorita centrale. Il contratto gestisce tutte le distribuzioni in modo automatico e trasparente.',
    nl: 'Gedecentraliseerd protocol op de Polygon-blockchain. Alle betalingen in USDC gaan rechtstreeks naar uw wallet via een smart contract — geen tussenpersonen, geen centraal gezag. Het contract verwerkt alle verdelingen automatisch en transparant.',
    ro: 'Protocol descentralizat pe blockchain-ul Polygon. Toate platile in USDC merg direct in portofelul tau prin smart contract — fara intermediari, fara autoritate centrala. Contractul gestioneaza toate distributiile automat si transparent.',
    cs: 'Decentralizovaný protokol na blockchainu Polygon. Všechny platby v USDC jdou prímo do vaší peněženky přes smart kontrakt — žadní prostředníci, žadná centrální autorita. Kontrakt zpracovava všechny distribuce automaticky a transparentně.',
    fa: 'پروتکل غیرمتمرکز روی بلاکچین Polygon. تمام پرداخت‌ها به صورت USDC مستقیماً به کیف پول شما از طریق قرارداد هوشمند ارسال می‌شود — بدون واسطه و بدون مرجع مرکزی. قرارداد تمام توزیع‌ها را به صورت خودکار و شفاف انجام می‌دهد.',
    bn: 'Polygon ব্লকচেইনে বিকেন্দ্রীভূত প্রোটোকল। USDC-তে সমস্ত পেমেন্ট স্মার্ট কন্ট্রাক্টের মাধ্যমে সরাসরি আপনার ওয়ালেটে যায় — কোনো মধ্যস্থতাকারী নেই, কোনো কেন্দ্রীয় কর্তৃপক্ষ নেই। কন্ট্রাক্ট সমস্ত বিতরণ স্বয়ংক্রিয়ভাবে ও স্বচ্ছভাবে পরিচালনা করে।',
    sw: 'Itifaki iliyogatuliwa kwenye blockchain ya Polygon. Malipo yote ya USDC yanakwenda moja kwa moja kwenye pochi yako kupitia mkataba wa kisasa — hakuna madalali, hakuna mamlaka kuu. Mkataba unashughulikia usambazaji wote kiotomatiki na kwa uwazi.'
  },
