    vi: 'Hệ thống thu nhập phi tập trung',
    ko: '탈중앙화 수익 시스템',
    ja: '分散型収益システム',
    hi: 'विकेंद्रीकृत कमाई प्रणाली',
    zh: '去中心化收益系统',
